const payload = $json.body ?? $json;
const required = ['title', 'propertyType', 'area', 'city', 'countryCode', 'sourceType'];
for (const key of required) {
  if (!payload[key]) throw new Error(`Missing required listing field: ${key}`);
}
if (payload.privateDetails) throw new Error('Private owner/property details are not accepted by this webhook');
if (!['approved_feed', 'partner_feed', 'public_api'].includes(payload.sourceType)) throw new Error('Source type is not an approved automated source');
return [{ json: payload }];
